def design(rng, n, p, case):
    x = rng.normal(size=(n, p)) / np.sqrt(n)
    if case == 'cluster':
        x = 0.48 * x + 0.88 * np.repeat(rng.normal(size=(n, (p + 2) // 3)) / np.sqrt(n), 3, axis=1)[:, :p]
    if case == 'collinear':
        x = 0.17 * x + 0.98 * np.repeat(rng.normal(size=(n, (p + 1) // 2)) / np.sqrt(n), 2, axis=1)[:, :p]
    if case == 'scaled':
        x *= np.geomspace(0.15, 4, p)
    if case == 'bridge':
        x = np.zeros((n, p))
        rr = np.arange(n - 1)
        j = rng.integers(p, size=n - 1)
        x[rr, j] = rng.normal(size=n - 1)
        x[-1, :] = 0.07
        x /= np.linalg.norm(x, axis=0)
    return x
